body {
  background-color: #f5f6f8;
  color: #18181b;
  font-family: system-ui, "Segoe UI", sans-serif;
  line-height: 1.6;
  padding: 16px;
}

h1 { font-size: 26px; }
h2 { font-size: 16px; margin: 0 0 8px; }

.suite {
  background-color: #ffffff;
  padding: 16px;
  border-radius: 10px;
  margin-bottom: 12px;
  border-left: 4px solid #e4e4e7;
}

.suite.ok { border-left-color: #0a7a35; }
.suite.bad { border-left-color: #b91c1c; }

.suite ul {
  list-style: none;
  padding: 0;
  margin: 0;
}

.suite li {
  padding: 4px 0;
  font-size: 14px;
  border-bottom: 1px solid #f4f4f5;
}

.suite li:last-child { border-bottom: none; }

.suite li.ok { color: #14532d; }
.suite li.bad { color: #991b1b; }

// Shop.mn-ий агуулахын АСИНХРОН функц. Энэ файлыг өөрчлөх шаардлагагүй —
// таны ажил бол энэ функцийг ШАЛГАХ тест бичих.
//
// fetchStock(productId) нь агуулахаас барааны үлдэгдлийг Promise хэлбэрээр буцаана:
//   - бараа олдвол үлдэгдэл тоог resolve хийнэ (0 байж болно),
//   - бараа олдохгүй бол алдаа reject хийнэ.

function fetchStock(productId) {
  const catalog = { coat: 5, hat: 0 };
  return new Promise((resolve, reject) => {
    setTimeout(() => {
      if (Object.prototype.hasOwnProperty.call(catalog, productId)) {
        resolve(catalog[productId]);
      } else {
        reject(new Error("Бараа олдсонгүй: " + productId));
      }
    }, 5);
  });
}

window.SHOP = { fetchStock };

// Shop.mn-ий АСИНХРОН тестүүд.
// it("тайлбар", async () => { await expect(...).resolves.toBe(...); });

function tests() {
  it("агуулахад байгаа барааны үлдэгдлийг буцаана", async () => {
    await expect(fetchStock("coat")).resolves.toBe(5);
  });

  // энд бичнэ үү
}

window.tests = tests;

// Жижиг АСИНХРОН тест ажиллуулагч. Энэ файлыг өөрчлөх шаардлагагүй.
//
// Async тестийн ялгаа: тестийн бие `async` бөгөөд `await` ашиглана.
// Ажиллуулагч тест бүрийг дуустал нь хүлээгээд (`await`) дараагийнхийг эхлүүлнэ.
//
// Таны тестийг ХОЁР удаа ажиллуулна:
//   1) зөв хувилбар дээр — бүгд ДАВАХ ёстой,
//   2) санаатай эвдэрсэн хувилбар бүр дээр — дор хаяж нэг нь УНАХ ёстой.

const MUTANTS = {
  alwaysOne: {
    label: "Ямар ч барааны үлдэгдлийг 1 гэж буцаадаг",
    fn: "fetchStock",
    impl: (productId) =>
      new Promise((resolve, reject) => {
        const catalog = { coat: 5, hat: 0 };
        setTimeout(() => {
          if (Object.prototype.hasOwnProperty.call(catalog, productId)) resolve(1);
          else reject(new Error("Бараа олдсонгүй: " + productId));
        }, 5);
      }),
  },
  noReject: {
    label: "Байхгүй бараанд алдаа шидэхийн оронд 0 буцаадаг",
    fn: "fetchStock",
    impl: (productId) =>
      new Promise((resolve) => {
        const catalog = { coat: 5, hat: 0 };
        setTimeout(() => resolve(catalog[productId] !== undefined ? catalog[productId] : 0), 5);
      }),
  },
  zeroTruthy: {
    label: "Үлдэгдэл 0 байхыг «байхгүй» гэж андуурдаг",
    fn: "fetchStock",
    impl: (productId) =>
      new Promise((resolve, reject) => {
        const catalog = { coat: 5, hat: 0 };
        setTimeout(() => {
          if (catalog[productId]) resolve(catalog[productId]);
          else reject(new Error("Бараа олдсонгүй: " + productId));
        }, 5);
      }),
  },
};

const output = document.getElementById("output");

let current = null;

function it(name, body) {
  current.queue.push({ name: name, body: body });
}

async function runCase(test) {
  const result = { name: test.name, passed: true, message: null };

  try {
    await test.body();
  } catch (problem) {
    result.passed = false;
    result.message = problem.message;
  }

  current.cases.push(result);
  if (!result.passed) current.failed += 1;
  current.total += 1;
}

function expect(actual) {
  return {
    toBe(expected) {
      if (!Object.is(actual, expected)) {
        throw new Error("хүлээсэн " + JSON.stringify(expected) + ", гарсан " + JSON.stringify(actual));
      }
    },
    toEqual(expected) {
      if (JSON.stringify(actual) !== JSON.stringify(expected)) {
        throw new Error("хүлээсэн " + JSON.stringify(expected) + ", гарсан " + JSON.stringify(actual));
      }
    },
    get resolves() {
      return {
        async toBe(expected) {
          const value = await actual;
          if (!Object.is(value, expected)) {
            throw new Error("resolve хүлээсэн " + JSON.stringify(expected) + ", гарсан " + JSON.stringify(value));
          }
        },
      };
    },
    get rejects() {
      return {
        async toThrow(message) {
          let thrown = null;
          try {
            await actual;
          } catch (problem) {
            thrown = problem;
          }
          if (!thrown) throw new Error("reject хийх ёстой байсан ч resolve хийсэн");
          if (message !== undefined && !String(thrown.message).includes(message)) {
            throw new Error("алдааны мессежид «" + message + "» байх ёстой, гарсан: " + thrown.message);
          }
        },
      };
    },
  };
}

window.it = it;
window.expect = expect;

async function runSuite(label) {
  current = { label: label, queue: [], cases: [], failed: 0, total: 0 };
  try {
    tests();
    for (const test of current.queue) {
      await runCase(test);
    }
  } catch (problem) {
    current.cases.push({ name: "(тест ажиллуулахад алдаа)", passed: false, message: problem.message });
    current.failed += 1;
    current.total += 1;
  }
  return current;
}

function useImplementation(overrides) {
  window.fetchStock = overrides.fetchStock || SHOP.fetchStock;
}

function panel(title, className, lines) {
  const box = document.createElement("section");
  box.className = "suite " + className;

  const heading = document.createElement("h2");
  heading.textContent = title;
  box.append(heading);

  const list = document.createElement("ul");
  for (const line of lines) {
    const li = document.createElement("li");
    li.className = line.ok ? "ok" : "bad";
    li.textContent = (line.ok ? "✓ " : "✗ ") + line.text;
    list.append(li);
  }
  box.append(list);
  output.append(box);
}

(async function () {
  window.TEST_REPORT = {};

  // 1. Зөв хувилбар дээр.
  useImplementation({});
  const correct = await runSuite("correct");
  window.TEST_REPORT.correct = { failed: correct.failed, total: correct.total };

  panel(
    "Зөв хувилбар — " + (correct.total - correct.failed) + "/" + correct.total,
    correct.failed === 0 ? "ok" : "bad",
    correct.cases.map((c) => ({ ok: c.passed, text: c.name + (c.passed ? "" : " — " + c.message) })),
  );

  // 2. Эвдэрсэн хувилбар бүр дээр: тестүүд алдааг барих ёстой.
  const caught = [];
  for (const key of Object.keys(MUTANTS)) {
    const mutant = MUTANTS[key];
    useImplementation({ [mutant.fn]: mutant.impl });
    const run = await runSuite(key);
    window.TEST_REPORT[key] = { failed: run.failed, total: run.total };
    caught.push({ ok: run.failed > 0, text: mutant.label });
  }

  panel("Эвдэрсэн хувилбаруудыг барьсан эсэх", caught.every((c) => c.ok) ? "ok" : "bad", caught);

  useImplementation({});
  document.body.dataset.ready = "1";
})();

