function tests() {
  it("агуулахад байгаа барааны үлдэгдлийг буцаана", async () => {
    await expect(fetchStock("coat")).resolves.toBe(5);
  });

  it("үлдэгдэл тэг байвал 0-ийг буцаана", async () => {
    await expect(fetchStock("hat")).resolves.toBe(0);
  });

  it("байхгүй бараа алдаа шиднэ", async () => {
    await expect(fetchStock("байхгүй")).rejects.toThrow("олдсонгүй");
  });

  it("await ашиглан үлдэгдлийг шалгана", async () => {
    const count = await fetchStock("coat");
    expect(count).toBe(5);
  });
}

window.tests = tests;
